<?php
namespace App\Http\Controllers;use App\Models\PrivacyRequest;use Illuminate\Http\Request;
class PrivacyController extends Controller{public function portal(Request $r){return view('privacy.portal',['requests'=>PrivacyRequest::where('user_id',$r->user()->id)->latest()->get()]);}public function export(Request $r){$u=$r->user()->load(['driverProfile','sentMessages','receivedMessages']);$trips=\App\Models\Trip::where('passenger_id',$u->id)->orWhere('driver_id',$u->id)->get();$payments=\App\Models\Payment::where('user_id',$u->id)->get()->makeHidden(['provider_response']);$data=['generated_at'=>now()->toIso8601String(),'user'=>$u->only(['id','name','email','role','created_at']),'driver_profile'=>$u->driverProfile?->makeHidden(['account_number'])->toArray(),'trips'=>$trips->makeHidden(['pickup_pin'])->toArray(),'payments'=>$payments->toArray(),'messages_sent'=>$u->sentMessages->toArray(),'messages_received'=>$u->receivedMessages->toArray()];return response()->streamDownload(fn()=>print(json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)), 'llegamos-datos-'.$u->id.'.json',['Content-Type'=>'application/json']);}public function request(Request $r){$d=$r->validate(['type'=>'required|in:access,correction,deletion','details'=>'nullable|string|max:2000']);PrivacyRequest::create(['user_id'=>$r->user()->id,'type'=>$d['type'],'details'=>$d['details']??null]);return back()->with('success','Solicitud de privacidad registrada.');}public function admin(Request $r){return view('privacy.admin',['requests'=>PrivacyRequest::with('user:id,name,email')->latest()->paginate(30)]);}public function resolve(Request $r,PrivacyRequest $privacyRequest){$d=$r->validate(['status'=>'required|in:in_review,completed,rejected','resolution_notes'=>'required|string|max:2000']);$privacyRequest->update(['status'=>$d['status'],'resolution_notes'=>$d['resolution_notes'],'reviewed_by'=>$r->user()->id,'resolved_at'=>in_array($d['status'],['completed','rejected'])?now():null]);return back()->with('success','Solicitud actualizada.');}}